/* shadcn/ui's colours, from Amber Notes' tokens (they switch for dark mode by themselves). */
:root {
  --radius: 0.75rem;
  --background: var(--amber-bg);
  --foreground: var(--amber-text);
  --card: var(--amber-surface);
  --card-foreground: var(--amber-text);
  --popover: var(--amber-bg);
  --popover-foreground: var(--amber-text);
  /* Three ambers, each with one job, the same three the Mac app has:
     the accent (--amber-accent) for ticks, rings, bars and dots;
     --link, its ink shade, for amber text, which reads at 4.5:1 on the page and on a card;
     --primary, the primary button's fill: the accent deepened until a white label reads on it
     (stock amber gives #BB5B05, the fill of the Mac's own buttons). In dark mode the button is
     white with a black label, as the Mac's are: dark-mode buttons are white or black, never amber.
     A host that knows its own button colours sets --amber-button and --amber-on-button. */
  --primary: var(--amber-button, color-mix(in srgb, var(--amber-accent) 86%, black));
